<?php $xtreampiModules = is_array($modules ?? null) ? $modules : []; ?>
<section class="sc-modules"><div class="sc-page-heading"><div><p class="sc-eyebrow">System</p><h1>Modules</h1></div><div class="sc-page-actions"><a class="sc-button sc-button-secondary" href="modules?admin_ui=legacy"><i class="fe-corner-up-left" aria-hidden="true"></i> Open module manager</a></div></div><div class="sc-data-panel"><div class="sc-table-scroll"><table class="sc-data-table"><thead><tr><th>Module</th><th>Version</th><th>Status</th></tr></thead><tbody><?php foreach ($xtreampiModules as $xtreampiModule): ?><tr><td><div class="sc-table-identity"><strong><?php echo htmlspecialchars((string) ($xtreampiModule['name'] ?? $xtreampiModule['slug'] ?? 'Unnamed module'), ENT_QUOTES, 'UTF-8'); ?></strong><small><?php echo htmlspecialchars((string) ($xtreampiModule['slug'] ?? ''), ENT_QUOTES, 'UTF-8'); ?></small></div></td><td><?php echo htmlspecialchars((string) ($xtreampiModule['version'] ?? '—'), ENT_QUOTES, 'UTF-8'); ?></td><td><span class="sc-row-status <?php echo !empty($xtreampiModule['enabled']) ? 'is-active' : 'is-disabled'; ?>"><?php echo !empty($xtreampiModule['enabled']) ? 'Enabled' : 'Disabled'; ?></span></td></tr><?php endforeach; ?><?php if (!$xtreampiModules): ?><tr><td class="sc-table-state" colspan="3">No modules are installed.</td></tr><?php endif; ?></tbody></table></div></div></section>
